58	import org.springframework.security.access.prepost.PreAuthorize;
59	import org.springframework.web.bind.annotation.CrossOrigin;
60	import org.springframework.web.bind.annotation.RequestMapping;
61	import org.springframework.web.bind.annotation.RestController;
62	import org.springframework.web.util.UriComponentsBuilder;
63	
64	import jakarta.transaction.Transactional;
65	
66	/**
67	 * @author Vitaliy Fedoriv
68	 */
69	
70	@RestController
71	@CrossOrigin(exposedHeaders = "errors, content-type")
72	@RequestMapping("/api")
73	public class OwnerRestControllerV1 implements OwnersApi {
74	
75	    /**
76	     * Dedicated audit logger. On a successful owner create an audit line carrying the owner id,
77	     * the {@code customerCode} and the {@code registrationDate} is emitted to this named logger.
78	     */
79	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
80	
81	    private final ClinicService clinicService;
82	
83	    private final OwnerMapper ownerMapper;
84	
85	    private final PetMapper petMapper;
86	
87	    private final VisitMapper visitMapper;
88	
89	    public OwnerRestControllerV1(ClinicService clinicService,
90	                                 OwnerMapper ownerMapper,
91	                                 PetMapper petMapper,
92	                                 VisitMapper visitMapper) {
93	        this.clinicService = clinicService;
94	        this.ownerMapper = ownerMapper;
95	        this.petMapper = petMapper;
96	        this.visitMapper = visitMapper;
97	    }
98	
99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
102	        Collection<Owner> owners;
103	        if (lastName != null) {
104	            owners = this.clinicService.findOwnerByLastName(lastName);
105	        } else {
106	            owners = this.clinicService.findAllOwners();
107	        }
108	        if (owners.isEmpty()) {
109	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
110	        }
111	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
112	    }
113	
114	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
115	    @Override
116	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
117	        Owner owner = this.clinicService.findOwnerById(ownerId);
118	        if (owner == null) {
119	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
120	        }
121	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
122	    }
123	
124	    /**
125	     * Rejects an owner payload that is missing or blank in any of the required fields
126	     * (firstName, lastName, address, city, telephone). Bean Validation on the request body
127	     * already rejects {@code null} values and empty strings, but treats a whitespace-only
128	     * value as present; this guard closes that gap so a blank in any required field is
129	     * reported. The thrown exception is translated to a 400 whose {@code errors} array lists
130	     * the name of each offending field.
131	     */
132	    private void rejectMissingOrBlankFields(OwnerFieldsDto ownerFieldsDto, String normalizedAddress) {
133	        List<String> missing = new ArrayList<>();
134	        if (isBlank(ownerFieldsDto.getFirstName())) {
135	            missing.add("firstName");
136	        }
137	        if (isBlank(ownerFieldsDto.getLastName())) {
138	            missing.add("lastName");
139	        }
140	        if (isBlank(normalizedAddress)) {
141	            missing.add("address");
142	        }
143	        if (isBlank(ownerFieldsDto.getCity())) {
144	            missing.add("city");
145	        }
146	        if (isBlank(ownerFieldsDto.getTelephone())) {
147	            missing.add("telephone");
148	        }
149	        if (!missing.isEmpty()) {
150	            throw new MissingOwnerFieldsException(missing);
151	        }
152	    }
153	
154	    private static boolean isBlank(String value) {
155	        return value == null || value.isBlank();
156	    }
157	
158	    /**
159	     * Matches a well-formed E.164 telephone: a leading '+' followed by 8 to 15 digits.
160	     */
161	    private static final Pattern E164_PATTERN = Pattern.compile("\\+\\d{8,15}");
162	
163	    /**
164	     * Required national-number length per country calling code. When the normalized E.164 number
165	     * begins with one of these codes, the digits that follow must number exactly the mapped value:
166	     * '+61' (Australia) requires 9 national digits and '+1' (NANP) requires 10. Codes absent from
167	     * this map carry no per-country length rule beyond the generic E.164 8-to-15-digit bound.
168	     */
169	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
170	        "+61", 9,
171	        "+1", 10);
172	
173	    /**
174	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
175	     * stripped. When a leading '+' (with its country code) is present it is kept as-is; otherwise
176	     * the country code '+61' is assumed and a single leading '0' is dropped from the national
177	     * digits. The result must be a '+' followed by 8 to 15 digits, so e.g. '0412 345 678' is
178	     * stored as '+61412345678'. When the country code has a known national-number length ('+61'
179	     * requires 9 national digits, '+1' requires 10) the national digits must match it exactly. A
180	     * value that cannot form a valid E.164 number, or whose national length is wrong for its
181	     * country, is rejected via {@link InvalidTelephoneException}, which the exception handler
182	     * translates to a 400.
183	     */
184	    private static String normalizeTelephone(String telephone) {
185	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()\\[\\]]", "");
186	        String e164;
187	        if (cleaned.startsWith("+")) {
188	            e164 = cleaned;
189	        } else {
190	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
191	            e164 = "+61" + national;
192	        }
193	        if (!E164_PATTERN.matcher(e164).matches()) {
194	            throw new InvalidTelephoneException(telephone);
195	        }
196	        for (Map.Entry<String, Integer> rule : NATIONAL_NUMBER_LENGTHS.entrySet()) {
197	            String code = rule.getKey();
198	            if (e164.startsWith(code)) {
199	                int nationalLength = e164.length() - code.length();
200	                if (nationalLength != rule.getValue()) {
201	                    throw new InvalidTelephoneException(telephone);
202	                }
203	                break;
204	            }
205	        }
206	        return e164;
207	    }
208	
209	    /**
210	     * Matches a well-formed postcode: exactly four digits.
211	     */
212	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("\\d{4}");
213	
214	    /**
215	     * The canonical region for each city that has one. A city absent from this table has no known
216	     * region and so accepts any 4-digit postcode. This is the same fixed city-to-region table used
217	     * to derive an owner's locality.
218	     */
219	    private static final Map<String, String> CITY_REGION = Map.of(
220	        "Sydney", "NSW",
221	        "Melbourne", "VIC",
222	        "Brisbane", "QLD");
223	
224	    /**
225	     * The inclusive 4-digit postcode range for each region, as {@code {low, high}}: NSW 2000-2099,
226	     * VIC 3000-3099, QLD 4000-4099.
227	     */
228	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
229	        "NSW", new int[] {2000, 2099},
230	        "VIC", new int[] {3000, 3099},
231	        "QLD", new int[] {4000, 4099});
232	
233	    /**
234	     * Validates an owner's optional postcode. A {@code null} postcode is left as-is (the field is
235	     * optional). When present it must be exactly four digits; and when the owner's city maps to a
236	     * known region it must fall within that region's inclusive postcode range (NSW 2000-2099, VIC
237	     * 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode. An
238	     * invalid or out-of-range value is rejected via {@link InvalidPostcodeException}, which the
239	     * exception handler translates to a 400.
240	     */
241	    private static void validatePostcode(String city, String postcode) {
242	        if (postcode == null) {
243	            return;
244	        }
245	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
246	            throw new InvalidPostcodeException(postcode);
247	        }
248	        String region = CITY_REGION.get(city);
249	        if (region == null) {
250	            return;
251	        }
252	        int[] range = REGION_POSTCODES.get(region);
253	        int value = Integer.parseInt(postcode);
254	        if (value < range[0] || value > range[1]) {
255	            throw new InvalidPostcodeException(postcode);
256	        }
257	    }
258	
259	    /**
260	     * A pragmatic syntactic email check: a non-empty local part, an {@code @}, and a domain that
261	     * carries at least one dot, with no whitespace anywhere. Deliberately permissive — it accepts
262	     * ordinary addresses while rejecting obvious non-addresses such as one lacking an {@code @}.
263	     */
264	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
265	
266	    /**
267	     * Normalizes an optional owner email. A {@code null} email is left as-is (the field is
268	     * optional). When present it must be a syntactically valid address; a valid value is
269	     * lower-cased so it is stored and returned in canonical form. An invalid value is rejected via
270	     * {@link InvalidEmailException}, which the exception handler translates to a 400.
271	     */
272	    private static String normalizeEmail(String email) {
273	        if (email == null) {
274	            return null;
275	        }
276	        if (!EMAIL_PATTERN.matcher(email).matches()) {
277	            throw new InvalidEmailException(email);
278	        }
279	        return email.toLowerCase(Locale.ROOT);
280	    }
281	
282	    /**
283	     * The single derived identity of an owner, {@code normalizedTelephone + '|' + (email or empty)
284	     * + '|' + householdId}, into which all duplicate detection is consolidated. Two owners are the
285	     * same identity only when this whole key matches: because the normalized telephone is part of
286	     * the key, two members of the same household (same {@code householdId}) with different
287	     * telephones have different identity keys. A {@code null} email contributes an empty middle
288	     * segment. This is the value returned to callers as {@code identityKey}.
289	     */
290	    private static String identityKeyFor(String normalizedTelephone, String normalizedEmail, String householdId) {
291	        return normalizedTelephone + "|" + (normalizedEmail == null ? "" : normalizedEmail) + "|" + householdId;
292	    }
293	
294	    /**
295	     * Rejects a create whose derived identity collides with an existing owner's, reported via one
296	     * of the {@code Duplicate*} exceptions the handler translates to a 409. The former separate
297	     * telephone, email and household checks are now expressed through the components of the single
298	     * identity key:
299	     * <ul>
300	     *   <li>the normalized telephone matches an existing owner's canonical E.164 telephone (an
301	     *       existing value that cannot form a valid E.164 number is skipped rather than colliding);</li>
302	     *   <li>a present, lower-cased email matches an existing owner's lower-cased email (a {@code null}
303	     *       candidate email, being optional, is not compared, and existing owners without an email
304	     *       are skipped);</li>
305	     *   <li>the {@code householdId} matches an existing owner's - unless the caller opted into sharing
306	     *       a household via {@code sharesHousehold}, in which case the household component is not
307	     *       compared.</li>
308	     * </ul>
309	     */
310	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto, String normalizedTelephone,
311	                                         String normalizedEmail, String householdId) {
312	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
313	        for (Owner existing : this.clinicService.findAllOwners()) {
314	            String existingTelephone;
315	            try {
316	                existingTelephone = normalizeTelephone(existing.getTelephone());
317	            } catch (InvalidTelephoneException ex) {
318	                existingTelephone = null;
319	            }
320	            if (normalizedTelephone.equals(existingTelephone)) {
321	                throw new DuplicateTelephoneException(normalizedTelephone);
322	            }
323	            if (normalizedEmail != null) {
324	                String existingEmail = existing.getEmail();
325	                if (existingEmail != null && normalizedEmail.equals(existingEmail.toLowerCase(Locale.ROOT))) {
326	                    throw new DuplicateEmailException(normalizedEmail);
327	                }
328	            }
329	            if (!sharesHousehold
330	                && householdId.equals(householdIdFor(existing.getLastName(), existing.getAddress()))) {
331	                throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
332	            }
333	        }
334	    }
335	
336	    /**
337	     * Collapses a value for household comparison: leading and trailing whitespace is trimmed, any
338	     * internal run of whitespace is reduced to a single space, and the result is lower-cased. This
339	     * is how both {@code lastName} and {@code address} are compared so that differences of case or
340	     * spacing do not defeat the duplicate-household check.
341	     */
342	    private static String collapse(String value) {
343	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
344	    }
345	
346	    /**
347	     * Normalizes an owner's address into a canonical form applied on every create: leading and
348	     * trailing whitespace is trimmed, any internal run of whitespace is reduced to a single space,
349	     * the value is upper-cased, and common street-type abbreviations are expanded on a per-word
350	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The result is stored
351	     * and returned, and is the form every address comparison (duplicate-household detection and the
352	     * shared {@code householdId}) uses. A {@code null} or whitespace-only input normalizes to the
353	     * empty string, which the required-field guard then rejects. The transformation is idempotent,
354	     * so normalizing an already-normalized address is a no-op.
355	     */
356	    private static String normalizeAddress(String address) {
357	        if (address == null) {
358	            return "";
359	        }
360	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
361	        if (collapsed.isEmpty()) {
362	            return "";
363	        }
364	        String[] tokens = collapsed.split(" ");
365	        StringBuilder sb = new StringBuilder(collapsed.length());
366	        for (int i = 0; i < tokens.length; i++) {
367	            String token = tokens[i];
368	            switch (token) {
369	                case "ST" -> token = "STREET";
370	                case "RD" -> token = "ROAD";
371	                case "AVE" -> token = "AVENUE";
372	                default -> {
373	                }
374	            }
375	            if (i > 0) {
376	                sb.append(' ');
377	            }
378	            sb.append(token);
379	        }
380	        return sb.toString();
381	    }
382	
383	    /**
384	     * Builds the {@code customerCode} for a newly created owner, formatted
385	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where {@code CITY3} is the upper-cased first three letters of
386	     * {@code city}, {@code LAST3} the upper-cased first three letters of {@code lastName}, and
387	     * {@code NNNN} a per-city 4-digit zero-padded sequence equal to one more than the number of
388	     * owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
389	     */
390	    private String nextCustomerCode(String city, String lastName) {
391	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
392	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
393	        int sequence = 1;
394	        for (Owner existing : this.clinicService.findAllOwners()) {
395	            if (city.equalsIgnoreCase(existing.getCity())) {
396	                sequence++;
397	            }
398	        }
399	        return String.format("%s-%s-%04d", city3, last3, sequence);
400	    }
401	
402	    /**
403	     * Builds the {@code membershipNumber} for a newly created owner, formatted
404	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of the
405	     * {@code registrationDate} year (e.g. {@code 'SMI-0007-M26'}).
406	     */
407	    private static String membershipNumberFor(String customerCode, LocalDate registrationDate) {
408	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
409	    }
410	
411	    /**
412	     * Derives the stable {@code householdId} for an owner from the collapsed {@code lastName} and
413	     * {@code address} - the same pair used to detect a shared household. Because it is a pure
414	     * function of that pair (upper-case hex of SHA-256 over the two collapsed values), every owner
415	     * in the same household - whether created first or joining later via {@code sharesHousehold} -
416	     * receives the identical, non-blank identifier without needing to read any other owner's value.
417	     */
418	    private static String householdIdFor(String lastName, String address) {
419	        String key = collapse(lastName) + "\n" + normalizeAddress(address);
420	        try {
421	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
422	            StringBuilder sb = new StringBuilder(32);
423	            for (int i = 0; i < 8; i++) {
424	                sb.append(String.format("%02X", digest[i]));
425	            }
426	            return sb.toString();
427	        } catch (NoSuchAlgorithmException ex) {
428	            throw new IllegalStateException("SHA-256 not available", ex);
429	        }
430	    }
431	
432	    /**
433	     * Counts the existing owners who already share the given {@code firstName} and {@code lastName},
434	     * compared case-insensitively. This is evaluated before the new owner is saved, so it reflects
435	     * the state prior to this create and is stored on the owner as its {@code namesakeCount}.
436	     */
437	    private int countNamesakes(String firstName, String lastName) {
438	        int count = 0;
439	        for (Owner existing : this.clinicService.findAllOwners()) {
440	            if (firstName.equalsIgnoreCase(existing.getFirstName())
441	                && lastName.equalsIgnoreCase(existing.getLastName())) {
442	                count++;
443	            }
444	        }
445	        return count;
446	    }
447	
448	    /**
449	     * Counts the members of the household the new owner will belong to, as it stands after this
450	     * create. Every existing owner carrying the same {@code householdId} is counted, and the new
451	     * owner itself is added, so a value of 3 or more means the owner joins a household of at least
452	     * three members. This is evaluated with the new owner's {@code householdId} already set and is
453	     * stored on the owner as its {@code householdMemberCount}.
454	     */
455	    private int countHouseholdMembers(String householdId) {
456	        int count = 1;
457	        for (Owner existing : this.clinicService.findAllOwners()) {
458	            if (householdId.equals(existing.getHouseholdId())) {
459	                count++;
460	            }
461	        }
462	        return count;
463	    }
464	
465	    /**
466	     * The membership level ceiling assigned on create; level 4 is reserved for tenure and so is
467	     * never reached here.
468	     */
469	    private static final int MAX_MEMBERSHIP_LEVEL = 3;
470	
471	    /**
472	     * Computes the numeric {@code membershipLevel} for a newly created owner. It starts at 1,
473	     * gains 1 when an email is present, gains 1 when the owner's {@code namesakeCount} is 0, and
474	     * is capped at {@value #MAX_MEMBERSHIP_LEVEL} (level 4 is reserved for tenure). Evaluated after
475	     * the owner's email and namesakeCount have been set.
476	     */
477	    private static int membershipLevelFor(Owner owner) {
478	        int level = 1;
479	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
480	            level++;
481	        }
482	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
483	            level++;
484	        }
485	        return Math.min(level, MAX_MEMBERSHIP_LEVEL);
486	    }
487	
488	    /**
489	     * The maximum number of owners any single city may contain. A create whose city already
490	     * holds this many owners is rejected.
491	     */
492	    private static final int CITY_CAPACITY = 50;
493	
494	    /**
495	     * Rejects a create whose city already contains {@value #CITY_CAPACITY} or more owners,
496	     * compared case-insensitively - the same way the city is matched when building the
497	     * {@code customerCode} sequence. The count reflects the state prior to this create. A city
498	     * at capacity is reported via {@link CityAtCapacityException}, which the exception handler
499	     * translates to a 409.
500	     */
501	    private void rejectCityAtCapacity(String city) {
502	        int count = 0;
503	        for (Owner existing : this.clinicService.findAllOwners()) {
504	            if (city.equalsIgnoreCase(existing.getCity())) {
505	                count++;
506	            }
507	        }
508	        if (count >= CITY_CAPACITY) {
509	            throw new CityAtCapacityException(city);
510	        }
511	    }
512	
513	    /**
514	     * The maximum number of owners that may be created on any single day (by
515	     * {@code registrationDate}). A create attempted once this many owners already carry the
516	     * current day's registration date is rejected.
517	     */
518	    private static final int DAILY_OWNER_LIMIT = 100;
519	
520	    /**
521	     * Rejects a create once {@value #DAILY_OWNER_LIMIT} or more owners already carry the given
522	     * business-day-adjusted {@code registrationDate} (the date the new owner will itself receive).
523	     * The count reflects the state prior to this create. When the limit is reached the create is
524	     * reported via {@link DailyOwnerLimitExceededException}, which the exception handler translates
525	     * to a 429 Too Many Requests.
526	     */
527	    private void rejectDailyOwnerLimit(LocalDate registrationDate) {
528	        int count = 0;
529	        for (Owner existing : this.clinicService.findAllOwners()) {
530	            if (registrationDate.equals(existing.getRegistrationDate())) {
531	                count++;
532	            }
533	        }
534	        if (count >= DAILY_OWNER_LIMIT) {
535	            throw new DailyOwnerLimitExceededException();
536	        }
537	    }
538	
539	    /**
540	     * The number of owners that must already carry a given {@code registrationDate} before a
541	     * create on that date is flagged with a bulk-signup warning. Once <em>more than</em> this
542	     * many owners already exist for the day, the new owner's {@code bulkSignupWarning} is true.
543	     */
544	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
545	
546	    /**
547	     * Computes the {@code bulkSignupWarning} for a create on the given business-day-adjusted
548	     * {@code registrationDate}: true when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners
549	     * have already been created for that date, otherwise false. The count reflects the state prior
550	     * to this create, matching how the daily-limit rule accumulates.
551	     */
552	    private boolean bulkSignupWarningFor(LocalDate registrationDate) {
553	        int count = 0;
554	        for (Owner existing : this.clinicService.findAllOwners()) {
555	            if (registrationDate.equals(existing.getRegistrationDate())) {
556	                count++;
557	            }
558	        }
559	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
560	    }
561	
562	    /**
563	     * Rolls an effective registration date forward onto a business day. A Saturday or Sunday is
564	     * advanced to the following Monday; a weekday is returned unchanged. This is applied to the
565	     * effective registration date - whether supplied in the request or defaulted to the server
566	     * date - so the stored {@code registrationDate}, and everything derived from it, always falls
567	     * on a business day.
568	     */
569	    private static LocalDate toBusinessDay(LocalDate date) {
570	        return switch (date.getDayOfWeek()) {
571	            case SATURDAY -> date.plusDays(2);
572	            case SUNDAY -> date.plusDays(1);
573	            default -> date;
574	        };
575	    }
576	
577	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
578	    @Override
579	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
580	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
581	        rejectMissingOrBlankFields(ownerFieldsDto, normalizedAddress);
582	        rejectCityAtCapacity(ownerFieldsDto.getCity());
583	        HttpHeaders headers = new HttpHeaders();
584	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
585	        owner.setAddress(normalizedAddress);
586	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
587	        owner.setTelephone(normalizedTelephone);
588	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
589	        owner.setEmail(normalizedEmail);
590	        validatePostcode(owner.getCity(), owner.getPostcode());
591	        String householdId = householdIdFor(owner.getLastName(), owner.getAddress());
592	        rejectDuplicateIdentity(ownerFieldsDto, normalizedTelephone, normalizedEmail, householdId);
593	        LocalDate effectiveDate = owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
594	        LocalDate registrationDate = toBusinessDay(effectiveDate);
595	        rejectDailyOwnerLimit(registrationDate);
596	        owner.setBulkSignupWarning(bulkSignupWarningFor(registrationDate));
597	        owner.setRegistrationDate(registrationDate);
598	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
599	        owner.setMembershipNumber(membershipNumberFor(owner.getCustomerCode(), owner.getRegistrationDate()));
600	        owner.setHouseholdId(householdId);
601	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
602	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
603	        owner.setMembershipLevel(membershipLevelFor(owner));
604	        this.clinicService.saveOwner(owner);
605	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
606	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
607	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
608	        headers.setLocation(UriComponentsBuilder.newInstance()
609	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
610	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
611	    }
612	
613	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
614	    @Override
615	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
616	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
617	        if (currentOwner == null) {
618	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
619	        }
620	        currentOwner.setAddress(ownerFieldsDto.getAddress());
621	        currentOwner.setCity(ownerFieldsDto.getCity());
622	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
623	        currentOwner.setLastName(ownerFieldsDto.getLastName());
624	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
625	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
626	        this.clinicService.saveOwner(currentOwner);
627	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
628	    }
629	
630	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
631	    @Transactional
632	    @Override
633	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
634	        Owner owner = this.clinicService.findOwnerById(ownerId);
635	        if (owner == null) {
636	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
637	        }
638	        this.clinicService.deleteOwner(owner);
639	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
640	    }
641	
642	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
643	    @Override
644	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
645	        Owner owner = this.clinicService.findOwnerById(ownerId);
646	        if (owner == null) {
647	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
648	        }
649	        HttpHeaders headers = new HttpHeaders();
650	        Pet pet = petMapper.toPet(petFieldsDto);
651	        owner.setId(ownerId);
652	        pet.setOwner(owner);
653	        pet.getType().setName(null);
654	        this.clinicService.savePet(pet);
655	        PetDto petDto = petMapper.toPetDto(pet);
656	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
657	            .buildAndExpand(pet.getId()).toUri());
658	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
659	    }
660	
661	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
662	    @Override
663	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
664	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
665	        if (currentOwner != null) {
666	            Pet currentPet = this.clinicService.findPetById(petId);
667	            if (currentPet != null) {
668	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
669	                currentPet.setName(petFieldsDto.getName());
670	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
671	                this.clinicService.savePet(currentPet);
672	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
673	            }
674	        }
675	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
676	    }
677	
678	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
679	    @Override
680	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
681	        HttpHeaders headers = new HttpHeaders();
682	        Visit visit = visitMapper.toVisit(visitFieldsDto);
683	        Pet pet = new Pet();
684	        pet.setId(petId);
685	        visit.setPet(pet);
686	        this.clinicService.saveVisit(visit);
687	        VisitDto visitDto = visitMapper.toVisitDto(visit);
688	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
689	            .buildAndExpand(visit.getId()).toUri());
690	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
691	    }
692	
693	
694	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
695	    @Override
696	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
697	        Owner owner = this.clinicService.findOwnerById(ownerId);
698	        if (owner != null) {
699	            Pet pet = owner.getPet(petId);
700	            if (pet != null) {
701	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
702	            }
703	        }
704	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
705	    }
706	}
